mapper.select:
select a.repair_no as repairNo, a.report_address as address, a.fault_desc as fault, o.status as orderStatus, u.nickname as engineer, case when o.engineer_id=#{params.actor} then cast(o.id as char) end as ownOrderId from eoms_repair_apply a left join eoms_repair_order o on o.apply_id=a.id and o.tenant_id=a.tenant_id and o.del_flag='0' left join sys_user u on u.id=o.engineer_id where a.tenant_id=#{tenantId} and a.customer_id=#{customerId} and a.del_flag='0' and (a.status in ('WAIT','CONFIRM') or (a.status='ORDER' and o.status in ('WAIT_ACCEPT','ACCEPTED','PROCESSING')))
or o.engineer_id=#{params.dsUserId}
order by a.apply_time desc
